        if m.sum() >= min_valid:
            ic[d] = x[m].rank().corr(y[m].rank())
    return pd.Series(ic).sort_index()


def validate_factor(factor_id, factor_panel, prices, horizons=(1, 2, 3, 5, 10, 20),
